// ============================================================
// GENERATED LOCALIZATION RUNTIME HELPER
// ============================================================

Locale? _resolveGeneratedLocale(Locale locale) {
  if (localizedLabels.containsKey(locale)) {
    return locale;
  }

  final matches =
      localizedLabels.keys
          .where((x) => x.languageCode == locale.languageCode)
          .toList();

  if (matches.isEmpty) {
    return null;
  }

  final countryMatches =
      matches.where((x) => x.countryCode == locale.countryCode).toList();

  if (countryMatches.length == 1) {
    return countryMatches.first;
  }

  return matches.first;
}

String? getLocalizedValue(String key, Locale locale) {
  final resolvedLocale = _resolveGeneratedLocale(locale);

  if (resolvedLocale == null) {
    return null;
  }

  final data = localizedLabels[resolvedLocale];

  if (data == null) {
    return null;
  }

  dynamic current = data.toJson();

  for (final part in key.split('.')) {
    if (current is Map<String, Object?> && current.containsKey(part)) {
      current = current[part];
    } else {
      return null;
    }
  }

  return current?.toString();
}
